CREATE TABLE IF NOT EXISTS vocabulary_topics(id BIGINT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,name_en TEXT NOT NULL,name_vi TEXT NOT NULL,description_vi TEXT NOT NULL,icon TEXT NOT NULL,parent_id BIGINT REFERENCES vocabulary_topics(id) ON DELETE RESTRICT,active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS vocabulary_topic_words(word_id BIGINT NOT NULL REFERENCES library_words(id) ON DELETE CASCADE,topic_id BIGINT NOT NULL REFERENCES vocabulary_topics(id) ON DELETE CASCADE,sense_key TEXT NOT NULL DEFAULT '',review_status TEXT NOT NULL CHECK(review_status IN ('existing_published','pending','human_reviewed','rejected')),published BIGINT NOT NULL DEFAULT 0 CHECK(published IN (0,1)),confidence BIGINT NOT NULL DEFAULT 0 CHECK(confidence BETWEEN 0 AND 100),source_key TEXT NOT NULL,rationale TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,reviewed_at TEXT,reviewed_by TEXT NOT NULL DEFAULT '',PRIMARY KEY(word_id,topic_id,sense_key));
CREATE TABLE IF NOT EXISTS vocabulary_topic_reviews(id BIGSERIAL PRIMARY KEY,word_id BIGINT NOT NULL,topic_id BIGINT NOT NULL,sense_key TEXT NOT NULL DEFAULT '',reviewer_name TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('approve','reject')),reason TEXT NOT NULL,reviewed_at TEXT NOT NULL,FOREIGN KEY(word_id,topic_id,sense_key) REFERENCES vocabulary_topic_words(word_id,topic_id,sense_key) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_vocabulary_topic_words_topic ON vocabulary_topic_words(topic_id,published,word_id);
CREATE INDEX IF NOT EXISTS idx_vocabulary_topic_words_word ON vocabulary_topic_words(word_id,published,topic_id);
