nce','Science','Khoa học','Khái niệm khoa học và nghiên cứu.','🔬'),(21,'business-finance','Business & Finance','Kinh doanh & tài chính','Doanh nghiệp, thương mại và tài chính.','📈'),(22,'society-culture','Society & Culture','Xã hội & văn hóa','Cộng đồng, luật pháp, văn hóa và đời sống xã hội.','🌍'),(23,'places-directions','Places & Directions','Địa điểm & phương hướng','Địa điểm, vị trí và chỉ đường.','🧭'),(24,'weather-seasons','Weather & Seasons','Thời tiết & mùa','Thời tiết, khí hậu và các mùa.','🌦️') ON CONFLICT(id) DO NOTHING;
INSERT INTO vocabulary_topic_words(word_id,topic_id,sense_key,review_status,published,confidence,source_key,rationale,created_at)
SELECT w.id,CASE w.topic WHEN 'Time' THEN 1 WHEN 'Family' THEN 2 WHEN 'Food' THEN 3 WHEN 'Home' THEN 4 WHEN 'School' THEN 5 WHEN 'Work' THEN 6 WHEN 'Travel' THEN 7 WHEN 'Health' THEN 10 WHEN 'Technology' THEN 12 WHEN 'Nature' THEN 13 WHEN 'Feelings' THEN 17 WHEN 'Communication' THEN 19 WHEN 'People' THEN 22 WHEN 'Society' THEN 22 END,'','existing_published',1,100,'library_words.topic','Inherited from the topic field of already-published vocabulary; this is not a new human-review claim.',CURRENT_TIMESTAMP::text FROM library_words w WHERE w.reviewed=1 AND w.topic IN ('Time','Family','Food','Home','School','Work','Travel','Health','Technology','Nature','Feelings','Communication','People','Society') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION validate_vocabulary_topic_publish_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.published=1 AND OLD.published=0 AND (NOT EXISTS(SELECT 1 FROM library_words w WHERE w.id=NEW.word_id AND w.reviewed=1) OR NEW.review_status<>'human_reviewed' OR NOT EXISTS(SELECT 1 FROM vocabulary_topic_reviews r WHERE r.word_id=NEW.word_id AND r.topic_id=NEW.topic_id AND r.sense_key=NEW.sense_key AND r.decision='approve' AND btrim(r.reviewer_name)<>'')) THEN RAISE EXCEPTION 'Human review evidence and a published word are required for a new topic mapping'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS validate_vocabulary_topic_publish ON vocabulary_topic_words; CREATE TRIGGER validate_vocabulary_topic_publish BEFORE UPDATE OF published ON vocabulary_topic_words FOR EACH ROW EXECUTE FUNCTION validate_vocabulary_topic_publish_fn();
CREATE OR REPLACE FUNCTION immutable_vocabulary_topic_reviews_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'topic review audit log is immutable'; END $$;
DROP TRIGGER IF EXISTS immutable_vocabulary_topic_reviews_update ON vocabulary_topic_reviews; CREATE TRIGGER immutable_vocabulary_topic_reviews_update BEFORE UPDATE ON vocabulary_topic_reviews FOR EACH ROW EXECUTE FUNCTION immutable_vocabulary_topic_reviews_fn();
DROP TRIGGER IF EXISTS immutable_vocabulary_topic_reviews_delete ON vocabulary_topic_reviews; CREATE TRIGGER immutable_vocabulary_topic_reviews_delete BEFORE DELETE ON vocabulary_topic_reviews FOR EACH ROW EXECUTE FUNCTION immutable_vocabulary_topic_reviews_fn();
